create or replace function private.guard_requester_ticket_update() returns trigger language plpgsql security definer set search_path=public,pg_catalog as $$ begin if auth.uid()=old.requester_id and not private.has_company_role(old.company_id,array['admin'::membership_role,'hr'::membership_role,'manager'::membership_role]) then if new.company_id is distinct from old.company_id or new.requester_id is distinct from old.requester_id or new.created_by is distinct from old.created_by or new.status is distinct from old.status or new.accepted_by is distinct from old.accepted_by or new.accepted_at is distinct from old.accepted_at or new.resolved_at is distinct from old.resolved_at or new.closed_at is distinct from old.closed_at or new.due_at is distinct from old.due_at or new.department_id is distinct from old.department_id or new.team_id is distinct from old.team_id or new.archived_at is distinct from old.archived_at or new.first_response_due_at is distinct from old.first_response_due_at or new.first_responded_at is distinct from old.first_responded_at or new.sla_policy_id is distinct from old.sla_policy_id or new.sla_breached_at is distinct from old.sla_breached_at or new.escalation_level is distinct from old.escalation_level then raise exception 'Requesters cannot modify ticket workflow or ownership'; end if; end if; return new; end; $$;
drop trigger if exists guard_requester_ticket_update on public.tickets;
create trigger guard_requester_ticket_update before update on public.tickets for each row execute function private.guard_requester_ticket_update();
